import java.nio.charset.*;import java.nio.file.*;import java.sql.*;import java.util.regex.*;
public class CountInternationalHighSchools{public static void main(String[]a)throws Exception{String y=Files.readString(Path.of("src/main/resources/application.yml"),StandardCharsets.UTF_8);try(Connection c=DriverManager.getConnection(v(y,"url").replace("192.168.3.5","127.0.0.1"),v(y,"username"),v(y,"password"));var s=c.createStatement()){String[] qs={"SELECT COUNT(*) FROM school WHERE is_active=1 AND grades LIKE '%高中%'","SELECT COUNT(*) FROM school WHERE is_active=1 AND xueweigui_school_id IS NOT NULL AND grades LIKE '%高中%'","SELECT grades,COUNT(*) FROM school WHERE is_active=1 GROUP BY grades ORDER BY grades"};for(String q:qs){try(var r=s.executeQuery(q)){while(r.next()){for(int i=1;i<=r.getMetaData().getColumnCount();i++)System.out.print((i==1?"":"\t")+r.getString(i));System.out.println();}}}}}static String v(String y,String k){var m=Pattern.compile("(?m)^\\s*"+k+":\\s*([^\\r\\n#]+)").matcher(y);m.find();String z=m.group(1).trim();var p=Pattern.compile("\\$\\{([^:}]+)(?::([^}]*))?}").matcher(z);if(!p.matches())return z;String e=System.getenv(p.group(1));return e!=null&&!e.isBlank()?e:p.group(2);}}
